[DataContract]public sealed class LoopSource {
[DataMember,Browsable(false)]public string Engine{get;set;}[DataMember,DisplayName("Tensão entre fases do equivalente (V)")]public double LineVoltageV{get;set;}[DataMember,DisplayName("Frequência dos dados (Hz)")]public double FrequencyHz{get;set;}[DataMember,DisplayName("Fonte: R de fase (Ω)")]public double? PhaseROhm{get;set;}[DataMember,DisplayName("Fonte: X de fase (Ω)")]public double? PhaseXOhm{get;set;}[DataMember,DisplayName("Fonte: R de neutro (Ω)")]public double? NeutralROhm{get;set;}[DataMember,DisplayName("Fonte: X de neutro (Ω)")]public double? NeutralXOhm{get;set;}[DataMember,DisplayName("Fonte: R do retorno PE/terra (Ω)")]public double? PEROhm{get;set;}[DataMember,DisplayName("Fonte: X do retorno PE/terra (Ω)")]public double? PEXOhm{get;set;}[DataMember,DisplayName("Fonte: R do PEN (Ω)")]public double? PENROhm{get;set;}[DataMember,DisplayName("Fonte: X do PEN (Ω)")]public double? PENXOhm{get;set;}[DataMember,DisplayName("Autorizar R de fase derivada da seção")]public bool AllowDerivedPhaseResistance{get;set;}[DataMember,DisplayName("IT: condutância por fase (S)")]public double? ITConductanceSiemensPerPhase{get;set;}[DataMember,DisplayName("IT: capacitância por fase (nF)")]public double? ITCapacitanceNFPerPhase{get;set;}[DataMember,DisplayName("IT: condutância do neutro (S)")]public double? ITNeutralConductanceSiemens{get;set;}[DataMember,DisplayName("IT: capacitância do neutro (nF)")]public double? ITNeutralCapacitanceNF{get;set;}[DataMember,DisplayName("Referência dos dados/caso")]public string Reference{get;set;}[DataMember,DisplayName("Versão do equivalente")]public string DataVersion{get;set;}[DataMember,DisplayName("Condições e hipóteses")]public string Conditions{get;set;}
public LoopSource(){Engine=FaultLoops.EngineId;Reference=DataVersion=Conditions="";}public LoopSource Copy(){return (LoopSource)MemberwiseClone();}
public void Validate(){if(Engine!=FaultLoops.EngineId)throw new InvalidDataException("Revisão de laços desconhecida.");Project.Range(LineVoltageV,1,1e6,"tensão do equivalente");Project.Range(FrequencyHz,1,1000,"frequência do equivalente");foreach(var x in new[]{PhaseROhm,PhaseXOhm,NeutralROhm,NeutralXOhm,PEROhm,PEXOhm,PENROhm,PENXOhm,ITConductanceSiemensPerPhase,ITCapacitanceNFPerPhase,ITNeutralConductanceSiemens,ITNeutralCapacitanceNF})if(x.HasValue)Project.Range(x.Value,0,1e15,"impedância/fuga do equivalente");foreach(var s in new[]{Reference,DataVersion,Conditions})ReturnSizing.Text(s,false);}
}
[DataContract]public sealed class LoopFaultCase {
[DataMember,Browsable(false)]public string Engine{get;set;}[DataMember,DisplayName("Tipo de falta")]public LoopFaultKind Kind{get;set;}[DataMember,DisplayName("Condutor ativo da falta")]public FaultLive Live{get;set;}[DataMember,DisplayName("R da falta (Ω), declarar zero se ideal")]public double FaultROhm{get;set;}[DataMember,DisplayName("X da falta (Ω), declarar zero se ideal")]public double FaultXOhm{get;set;}[DataMember,DisplayName("Segundo circuito (ID), somente IT2")]public string SecondCircuitId{get;set;}[DataMember,DisplayName("Segundo condutor ativo, somente IT2")]public FaultLive SecondLive{get;set;}[DataMember,DisplayName("R da segunda falta (Ω), IT2")]public double SecondFaultROhm{get;set;}[DataMember,DisplayName("X da segunda falta (Ω), IT2")]public double SecondFaultXOhm{get;set;}[DataMember,DisplayName("Referência dos dados/caso")]public string Reference{get;set;}[DataMember,DisplayName("Condições e hipóteses")]public string Conditions{get;set;}
public LoopFaultCase(){Engine=FaultLoops.EngineId;SecondCircuitId=Reference=Conditions="";}public LoopFaultCase Copy(){return (LoopFaultCase)MemberwiseClone();}
public void Validate(){if(Engine!=FaultLoops.EngineId||!Enum.IsDefined(typeof(LoopFaultKind),Kind)||!Enum.IsDefined(typeof(FaultLive),Live)||!Enum.IsDefined(typeof(FaultLive),SecondLive))throw new InvalidDataException("Caso/revisão de falta desconhecidos.");foreach(var x in new[]{FaultROhm,FaultXOhm,SecondFaultROhm,SecondFaultXOhm})Project.Range(x,0,1e12,"impedância da falta");foreach(var s in new[]{SecondCircuitId,Reference,Conditions})ReturnSizing.Text(s,false);if(Kind!=LoopFaultKind.ITSecond&&(SecondCircuitId!=""||SecondFaultROhm!=0||SecondFaultXOhm!=0))throw new InvalidDataException("Campos da segunda falta não se aplicam a este caso.");}
}
public sealed partial class Project{[DataMember(Order=113),Browsable(false)]public LoopSource LoopSource{get;set;}}
public sealed partial class Circuit{[DataMember(Order=113),Browsable(false)]public LoopFaultCase LoopFault{get;set;}}
public enum FaultVoltageReference{Unknown,RemoteEarth,SourceNeutral}
public sealed class FaultLoopResult {public FaultVoltageReference MetalReference;public string Status,Detail;public Complex? Current,LoopImpedance,MetalVoltage,ResidualAtOrigin;public Complex[] BusVoltages;public double? CurrentA{get{return Current.HasValue?(double?)Complex.Abs(Current.Value):null;}}public double? MetalVoltageV{get{return MetalVoltage.HasValue?(double?)Complex.Abs(MetalVoltage.Value):null;}}}
public static class FaultLoops {
public const string EngineId="cs-lacos-desacoplados-v1";
sealed class Missing:Exception{public Missing(string message):base(message){}}
static void Need(bool condition,string text){if(!condition)throw new Missing(text);}
static Complex Z(double? r,double? x,string name){Need(r.HasValue&&x.HasValue,"R/X desconhecidos: "+name);return new Complex(r.Value,x.Value);}
static string N(Complex z){return z.Real.ToString("G9",System.Globalization.CultureInfo.InvariantCulture)+" +j("+z.Imaginary.ToString("G9",System.Globalization.CultureInfo.InvariantCulture)+")";}
public static List<Circuit> Path(Project p,Circuit c){var result=new List<Circuit>{c};var board=p.Boards.FirstOrDefault(b=>b.Circuits.Contains(c));Need(board!=null,"Circuito fora do projeto.");while(true){var parent=p.Boards.FirstOrDefault(b=>b.Circuits.Any(f=>f.ChildBoardId==board.Id));if(parent==null)break;var feeder=parent.Circuits.First(f=>f.ChildBoardId==board.Id);result.Insert(0,feeder);board=parent;}return result;}
static Board Root(Project p,Circuit c){return p.Boards.First(b=>b.Circuits.Contains(Path(p,c)[0]));}
static Complex PhaseSegment(LoopSource source,Circuit c,StringBuilder log){if(c.LengthM==0){log.AppendLine(c.Id+": fase com comprimento zero declarado.");return Complex.Zero;}Need(!String.IsNullOrWhiteSpace(c.Cable.Reference),"Referência de R/X do cabo ausente: "+c.Id);double resistance=c.Cable.ResistanceOhmKm;if(resistance==0){Need(source.AllowDerivedPhaseResistance&&c.CableMm2>0,"R de fase não informada nem derivação autorizada: "+c.Id);resistance=(c.Cable.Material==ConductorMaterial.Copper?23.7:37.6)/c.CableMm2;}Need(c.Cable.Parallel==1,"Paralelos exigem divisão de falta própria: "+c.Id);var z=new Complex(resistance,c.Cable.ReactanceOhmKm)*c.LengthM/1000;log.AppendLine(c.Id+": Zfase="+N(z)+" Ω; cabo "+c.Cable.Reference+(c.Cable.ResistanceOhmKm==0?"; R derivada da seção, condição operacional nominal":"; R declarada")+".");return z;}
static Complex ReturnSegment(Circuit c,bool neutral,StringBuilder log){var w=c.Conductors;Need(w!=null,"Condutores desconhecidos: "+c.Id);ReturnRole role;if(neutral){if(w.HasNeutral==true)role=ReturnRole.Neutral;else{Need(w.HasPEN==true,"Sem N/PEN declarado: "+c.Id);role=ReturnRole.PEN;}}else{if(w.HasPE==true)role=ReturnRole.PE;else{Need(w.HasPEN==true,"Sem PE/PEN declarado: "+c.Id);role=ReturnRole.PEN;}}if(c.LengthM==0){log.AppendLine(c.Id+": "+role+" com comprimento zero declarado.");return Complex.Zero;}Need(c.Cable.Parallel==1,"Retorno de paralelos não modelado: "+c.Id);var selected=c.ReturnSizing;var rating=selected==null?null:role==ReturnRole.Neutral?selected.Neutral:selected.Protective;Need(rating!=null&&rating.Role==role,"Seção/dados do retorno "+role+" não selecionados: "+c.Id);var z=Z(rating.ResistanceOhmKm,rating.ReactanceOhmKm,c.Id+" / "+role)*c.LengthM/1000;log.AppendLine(c.Id+": Z"+role+"="+N(z)+" Ω; "+rating.Reference+"; fonte "+rating.Source+"; versão "+rating.DataVersion+"; condições "+rating.Conditions+".");return z;}
static Complex SumPhase(Project p,Circuit c,StringBuilder log){Complex z=0;foreach(var part in Path(p,c))z+=PhaseSegment(p.LoopSource,part,log);return z;}
static Complex SumReturn(Project p,Circuit c,bool neutral,StringBuilder log){Complex z=0;foreach(var part in Path(p,c))z+=ReturnSegment(part,neutral,log);return z;}
static Complex SourceReturn(Project p,bool neutral){var source=p.LoopSource;var scheme=p.GroundingSource.Scheme;if(scheme==EarthingScheme.TNC||scheme==EarthingScheme.TNCS)return Z(source.PENROhm,source.PENXOhm,"PEN da fonte");return neutral?Z(source.NeutralROhm,source.NeutralXOhm,"N da fonte"):Z(source.PEROhm,source.PEXOhm,"PE/ligação de terra da fonte");}
static Complex Emf(Project p,FaultLive live){return live==FaultLive.Neutral?Complex.Zero:Complex.FromPolarCoordinates(p.Source.LineVoltage/Math.Sqrt(3),-2*Math.PI*(int)live/3);}
static void LiveAvailable(Project p,Circuit c,FaultLive live){Need(c.Conductors!=null,"Condutores do ponto de falta desconhecidos.");if(live==FaultLive.Neutral){Need(p.GroundingSource.NeutralDistributed==true&&(c.Conductors.HasNeutral==true||c.Conductors.HasPEN==true),"Neutro não disponível no ponto de falta.");return;}if(c.Phases==PhaseMode.Monofasico)Need(c.Conductors.Connection==LiveConnection.LineNeutral&&c.PhaseLabel==live.ToString(),"Fase solicitada não corresponde ao circuito fase-neutro.");else Need(c.Conductors.Connection==LiveConnection.ThreePhase||c.Conductors.Connection==LiveConnection.ThreePhaseNeutral,"Ligação trifásica desconhecida.");}
static Complex Divide(Complex voltage,Complex impedance){Need(Complex.Abs(impedance)>1e-15,"Laço ideal com impedância nula; corrente não finita não é calculada.");return voltage/impedance;}
public static FaultLoopResult Evaluate(Project p,Circuit c,LoopFaultCase fault){p.Validate();if(fault==null)return new FaultLoopResult{Status="Pendente",Detail="Caso de falta não informado."};fault.Validate();var log=new StringBuilder();try{var source=p.LoopSource;Need(source!=null,"Equivalente de laço da fonte não informado.");Need(p.GroundingSource!=null,"Esquema de aterramento tipado não informado.");Need(p.Source.SupportsVoltageSourceFaults,"Fonte não representa tensão de Thévenin não limitada neste cenário.");Need(source.LineVoltageV==p.Source.LineVoltage&&source.FrequencyHz==p.Frequency,"Tensão/frequência do equivalente não correspondem ao projeto.");Need(!String.IsNullOrWhiteSpace(source.Reference)&&!String.IsNullOrWhiteSpace(source.DataVersion)&&!String.IsNullOrWhiteSpace(source.Conditions)&&!String.IsNullOrWhiteSpace(fault.Reference)&&!String.IsNullOrWhiteSpace(fault.Conditions),"Referências/versão/condições do equivalente/caso incompletas.");Need(!new[]{source.Reference,source.DataVersion,source.Conditions,fault.Reference,fault.Conditions}.Any(x=>x.StartsWith("PREENCHER",StringComparison.OrdinalIgnoreCase)),"Modelo ainda não preenchido.");Need(Path(p,c).All(part=>Math.Abs(p.Boards.First(b=>b.Circuits.Contains(part)).Voltage-source.LineVoltageV)<.001),"Quadros não correspondem à tensão do equivalente único.");Need(Grounding.Complete(p,c),"Dados de aterramento/condutores incompletos no ponto de falta.");LiveAvailable(p,c,fault.Live);var phaseSource=Z(source.PhaseROhm,source.PhaseXOhm,"fase da fonte");Complex fz=new Complex(fault.FaultROhm,fault.FaultXOhm);Complex current,impedance,metal;var scheme=p.GroundingSource.Scheme;
if(fault.Kind==LoopFaultKind.LineNeutral){Need(fault.Live!=FaultLive.Neutral,"Selecione fase para falta fase-neutro.");LiveAvailable(p,c,FaultLive.Neutral);var phase=phaseSource+SumPhase(p,c,log);var ret=SourceReturn(p,true)+SumReturn(p,c,true,log);impedance=phase+ret+fz;current=Divide(Emf(p,fault.Live),impedance);return Result(log,source,fault,current,impedance,null,null,"Fase-neutro; Zfase+ZN/PEN+Zf, sem corrente pela terra.",FaultVoltageReference.Unknown,Complex.Zero);}
if(fault.Kind==LoopFaultKind.LineEarth){Need(fault.Live!=FaultLive.Neutral,"Selecione fase para falta fase-massa.");Need(scheme!=EarthingScheme.IT,"IT usa casos próprios de primeira/segunda falta.");Need(p.GroundingSource.NeutralConnection==NeutralEarthConnection.Direct,"Fonte diretamente aterrada não declarada.");var phase=phaseSource+SumPhase(p,c,log);var ret=SumReturn(p,c,false,log);if(scheme==EarthingScheme.TT){Need(p.GroundingSource.InstallationRaOhm.HasValue&&p.GroundingSource.SourceRbOhm.HasValue,"Ra/Rb desconhecidas.");ret+=p.GroundingSource.InstallationRaOhm.Value;impedance=phase+ret+Z(source.PEROhm,source.PEXOhm,"ligação eletrodo da fonte à estrela")+p.GroundingSource.SourceRbOhm.Value+fz;}else{Need(scheme==EarthingScheme.TNS||scheme==EarthingScheme.TNC||scheme==EarthingScheme.TNCS,"Esquema não suportado para este laço.");ret+=SourceReturn(p,false);impedance=phase+ret+fz;}current=Divide(Emf(p,fault.Live),impedance);metal=current*ret;return Result(log,source,fault,current,impedance,metal,null,"Fase-massa; elétrodos em série no TT, retorno metálico no TN. Potencial da massa relativo à referência remota/estrela do modelo.",scheme==EarthingScheme.TT?FaultVoltageReference.RemoteEarth:FaultVoltageReference.SourceNeutral,current);}
Need(scheme==EarthingScheme.IT,"Caso de falta IT exige esquema IT.");if(fault.Kind==LoopFaultKind.ITFirst)return FirstIT(p,c,fault,log,phaseSource);
var second=p.Boards.SelectMany(b=>b.Circuits).FirstOrDefault(part=>part.Id==fault.SecondCircuitId);Need(second!=null,"Segundo circuito não encontrado.");Need(Root(p,c)==Root(p,second),"Segunda falta entre raízes exige caminho PE externo explicitado; caso pendente.");Need(Grounding.Complete(p,second),"Aterramento/condutores do segundo ponto incompletos.");LiveAvailable(p,second,fault.SecondLive);Need(fault.Live!=fault.SecondLive,"Mesmo potencial ativo não caracteriza a segunda falta entre condutores distintos neste modelo.");var pathA=Path(p,c);var pathB=Path(p,second);int common=0;while(common<pathA.Count&&common<pathB.Count&&pathA[common]==pathB[common])common++;Complex liveA=fault.Live==FaultLive.Neutral?SourceReturn(p,true)+SumReturn(p,c,true,log):phaseSource+SumPhase(p,c,log);Complex liveB=fault.SecondLive==FaultLive.Neutral?SourceReturn(p,true)+SumReturn(p,second,true,log):phaseSource+SumPhase(p,second,log);Complex peBetween=0;foreach(var part in pathA.Skip(common).Concat(pathB.Skip(common)))peBetween+=ReturnSegment(part,false,log);impedance=liveA+liveB+peBetween+fz+new Complex(fault.SecondFaultROhm,fault.SecondFaultXOhm);current=Divide(Emf(p,fault.Live)-Emf(p,fault.SecondLive),impedance);log.AppendLine("Prefixo PE comum excluído: "+common+" trechos. ZPE entre massas="+N(peBetween)+" Ω. Ra/Rb não entram no laço metálico comum.");return Result(log,source,fault,current,impedance,null,null,"Segunda falta IT em grupo PE comum; diferença de fasores dos dois condutores ativos, sem fuga capacitiva no laço de alta corrente.",FaultVoltageReference.Unknown,pathB.Contains(c)?Complex.Zero:current);
}catch(Missing missing){return new FaultLoopResult{Status="Pendente",Detail=EngineId+". "+missing.Message+"\r\n"+log};}}
static FaultLoopResult Result(StringBuilder log,LoopSource source,LoopFaultCase fault,Complex current,Complex? z,Complex? metal,Complex[] bus,string method,FaultVoltageReference reference=FaultVoltageReference.Unknown,Complex? residual=null){Need(!double.IsNaN(current.Real)&&!double.IsInfinity(current.Real)&&!double.IsNaN(current.Imaginary)&&!double.IsInfinity(current.Imaginary),"Corrente não finita.");string detail=EngineId+"; fonte "+source.Reference+"; versão "+source.DataVersion+"; condições "+source.Conditions+"; caso "+fault.Kind+" / "+fault.Live+"; referência "+fault.Reference+"; condições "+fault.Conditions+".\r\n"+method+"\r\n"+log+"\r\nI="+N(current)+" A RMS; |I|="+Complex.Abs(current).ToString("G9",System.Globalization.CultureInfo.InvariantCulture)+" A; Zlaço="+(z.HasValue?N(z.Value):"MNA, sem impedância única de série")+" Ω; potencial da massa="+(metal.HasValue?Complex.Abs(metal.Value).ToString("G9",System.Globalization.CultureInfo.InvariantCulture)+" V":"não determinado neste caso")+"; referência de potencial="+reference+".\r\nEquivalente estrela desacoplado e nominal; não deriva sequência zero do curto3F, não inclui acoplamentos mútuos, paralelos, contribuição dinâmica de máquinas, mínimos/máximos IEC ou arco. Proximidade/rota e condições R/X devem corresponder à hipótese declarada. Cálculo de corrente não comprova seção, continuidade, IMD ou tempo/segurança da proteção.";return new FaultLoopResult{Status="Calculado no modelo declarado",Current=current,LoopImpedance=z,MetalVoltage=metal,MetalReference=reference,ResidualAtOrigin=residual,BusVoltages=bus,Detail=detail};}
static FaultLoopResult FirstIT(Project p,Circuit c,LoopFaultCase fault,StringBuilder log,Complex sourcePhase){var src=p.LoopSource;var earth=p.GroundingSource;Need(c.Phases==PhaseMode.Trifasico,"Primeira falta IT: equivalente de fugas concentradas requer circuito trifásico nesta revisão.");Need(src.ITConductanceSiemensPerPhase.HasValue&&src.ITCapacitanceNFPerPhase.HasValue,"Condutância/capacitância IT por fase desconhecidas.");Need(earth.InstallationRaOhm.HasValue,"Ra desconhecida.");Need(earth.NeutralConnection==NeutralEarthConnection.Isolated||earth.NeutralConnection==NeutralEarthConnection.Impedance,"Ligação IT isolada/por impedância não definida.");Complex zg=0,yg=0;if(earth.NeutralConnection==NeutralEarthConnection.Impedance){Need(earth.SourceRbOhm.HasValue,"Rb desconhecida no IT por impedância.");zg=Z(earth.GroundingROhm,earth.GroundingXOhm,"aterramento IT")+Z(src.PEROhm,src.PEXOhm,"ligação do aterramento da fonte")+earth.SourceRbOhm.Value;Need(Complex.Abs(zg)>1e-15,"Aterramento IT efetivamente direto não permitido.");yg=1/zg;}Complex phase=sourcePhase+SumPhase(p,c,log);Complex pe=SumReturn(p,c,false,log)+earth.InstallationRaOhm.Value;Complex faultPath=pe+new Complex(fault.FaultROhm,fault.FaultXOhm);Complex y=new Complex(src.ITConductanceSiemensPerPhase.Value,2*Math.PI*p.Frequency*src.ITCapacitanceNFPerPhase.Value*1e-9);bool hasNeutral=c.Conductors.HasNeutral==true;Complex yn=0,zn=0;if(hasNeutral){Need(src.ITNeutralConductanceSiemens.HasValue&&src.ITNeutralCapacitanceNF.HasValue,"Fuga do neutro IT distribuído desconhecida; declare G/C ou zero ideal.");yn=new Complex(src.ITNeutralConductanceSiemens.Value,2*Math.PI*p.Frequency*src.ITNeutralCapacitanceNF.Value*1e-9);if(yn!=Complex.Zero||fault.Live==FaultLive.Neutral)zn=SourceReturn(p,true)+SumReturn(p,c,true,log);else log.AppendLine("Fuga N declarada nula e falta na fase: IN=0 no ramo do neutro; impedância N não necessária para esta equação.");}else Need((!src.ITNeutralConductanceSiemens.HasValue||src.ITNeutralConductanceSiemens==0)&&(!src.ITNeutralCapacitanceNF.HasValue||src.ITNeutralCapacitanceNF==0),"Fuga de neutro declarada sem neutro no barramento equivalente.");int count=hasNeutral?6:5,star=3,neutral=4,currentIndex=count-1;var matrix=new Complex[count,count];var rhs=new Complex[count];for(int i=0;i<3;i++){matrix[i,i]=1+phase*y;matrix[i,star]=-1;if((int)fault.Live==i)matrix[i,currentIndex]=phase;rhs[i]=Emf(p,(FaultLive)i);matrix[star,i]=y;}matrix[star,star]=yg;matrix[star,currentIndex]=1;if(hasNeutral){int row=4;matrix[row,neutral]=1+zn*yn;matrix[row,star]=-1;if(fault.Live==FaultLive.Neutral)matrix[row,currentIndex]=zn;matrix[star,neutral]=yn;}matrix[count-1,fault.Live==FaultLive.Neutral?neutral:(int)fault.Live]=1;matrix[count-1,currentIndex]=-faultPath;var solved=Solve(matrix,rhs);log.AppendLine("IT: Y por fase="+N(y)+" S; Yneutro="+N(yn)+" S; Zneutro="+N(zn)+" Ω quando requerido; Zfase equivalente="+N(phase)+" Ω; caminho de falta="+N(faultPath)+" Ω; terra da fonte="+(earth.NeutralConnection==NeutralEarthConnection.Isolated?"isolada":N(zg)+" Ω")+"; deslocamento da estrela="+N(solved[star])+" V.");return Result(log,src,fault,solved[currentIndex],null,solved[currentIndex]*pe,solved.Take(count-1).ToArray(),"Primeira falta IT por MNA, três fugas de fase idênticas e fuga própria do neutro distribuído concentradas no barramento do ponto de falta; três impedâncias de fase iguais; não representa fugas distribuídas sem equivalente documentado.",FaultVoltageReference.RemoteEarth,-yg*solved[star]);}

static Complex[] Solve(Complex[,] input,Complex[] right){int n=right.Length;var a=(Complex[,])input.Clone();var b=(Complex[])right.Clone();for(int row=0;row<n;row++){double scale=0;for(int col=0;col<n;col++)scale=Math.Max(scale,Complex.Abs(a[row,col]));Need(scale>0,"Sistema MNA singular.");for(int col=0;col<n;col++)a[row,col]/=scale;b[row]/=scale;}for(int col=0;col<n;col++){int pivot=col;for(int row=col+1;row<n;row++)if(Complex.Abs(a[row,col])>Complex.Abs(a[pivot,col]))pivot=row;Need(Complex.Abs(a[pivot,col])>1e-14,"Sistema MNA singular ou mal condicionado.");if(pivot!=col){for(int j=col;j<n;j++){var t=a[col,j];a[col,j]=a[pivot,j];a[pivot,j]=t;}var v=b[col];b[col]=b[pivot];b[pivot]=v;}for(int row=col+1;row<n;row++){var f=a[row,col]/a[col,col];for(int j=col;j<n;j++)a[row,j]-=f*a[col,j];b[row]-=f*b[col];}}var x=new Complex[n];for(int row=n-1;row>=0;row--){var value=b[row];for(int col=row+1;col<n;col++)value-=a[row,col]*x[col];x[row]=value/a[row,row];}for(int row=0;row<n;row++){Complex residual=-right[row];double scale=Complex.Abs(right[row]);for(int col=0;col<n;col++){residual+=input[row,col]*x[col];scale+=Complex.Abs(input[row,col]*x[col]);}Need(Complex.Abs(residual)<=1e-9*Math.Max(1,scale),"Resíduo MNA excede tolerância.");}return x;}
}
